<x-app-layout>
    <div x-data="cvBuilder(@js($templates), @js($defaultTemplate))" x-init="init()" class="cv-builder-shell min-h-screen bg-[#f7f7f5] text-slate-900">
        <header class="sticky top-0 z-30 border-b border-[#deddd7] bg-white/95 backdrop-blur print:hidden"><div class="mx-auto flex max-w-[1700px] items-center justify-between gap-3 px-4 py-3 sm:px-6 lg:px-8"><a href="{{ url('/') }}" class="flex min-w-0 items-center gap-3"><span class="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[#222222] text-sm font-black text-[#f4c400]">CV</span><span class="min-w-0"><span class="block truncate text-sm font-extrabold tracking-tight text-slate-950">CV Builder</span><span class="hidden text-xs text-slate-500 sm:block">Craft a CV that gets noticed</span></span></a><nav class="hidden items-center gap-6 text-xs font-bold text-slate-500 xl:flex"><span class="text-[#222222]">Editor</span><span>Templates</span><span>My CV</span><span>Preview</span></nav><div class="flex items-center gap-2"><span class="hidden items-center gap-1.5 text-xs font-medium text-slate-500 sm:flex"><span class="h-2 w-2 rounded-full" :class="saveStatus === 'saved' ? 'bg-emerald-500' : saveStatus === 'saving' ? 'bg-[#f4c400]' : 'bg-slate-300'"></span><span x-text="saveLabel()"></span></span><button type="button" @click="mobilePreview = true" class="rounded-lg border border-slate-200 px-3 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50 lg:hidden">Preview</button><button type="button" @click="saveDraft()" class="rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm font-semibold text-slate-700 hover:border-[#f4c400]">Save</button><button type="button" @click="downloadPdf()" :disabled="downloading" class="rounded-lg bg-[#222222] px-3 py-2 text-sm font-semibold text-[#f4c400] shadow-sm hover:bg-black disabled:cursor-wait disabled:opacity-60" x-text="downloading ? 'Preparing...' : 'Download PDF'"></button></div></div></header>
        <main class="mx-auto max-w-[1700px] px-4 py-6 sm:px-6 lg:px-8"><div class="mb-6 flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between print:hidden"><div><p class="mb-1 text-xs font-bold uppercase tracking-[.2em] text-indigo-600">Build your CV</p><h1 class="text-2xl font-extrabold tracking-tight text-slate-950 sm:text-3xl">Create a CV employers can scan in seconds.</h1><p class="mt-1 text-sm text-slate-500">Complete each step at your pace. Your preview updates as you type.</p></div><div class="w-full max-w-sm rounded-xl border border-slate-200 bg-white p-4 shadow-sm"><div class="flex items-center justify-between text-xs font-bold uppercase tracking-wider text-slate-500"><span>CV completion</span><span class="text-indigo-600" x-text="completion() + '%' "></span></div><div class="mt-2 h-2 overflow-hidden rounded-full bg-slate-100"><div class="h-full rounded-full bg-indigo-600 transition-all" :style="`width: ${completion()}%`"></div></div><p class="mt-2 text-xs text-slate-500" x-text="completionHint()"></p></div></div>
            <div class="grid items-start gap-8 lg:grid-cols-[minmax(0,0.95fr)_minmax(520px,1.05fr)]"><form @input="markChanged()" @submit.prevent="saveDraft" class="space-y-4 print:hidden"><template x-for="(section, index) in sections" :key="section.id"><section class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><button type="button" @click="section.open = !section.open" class="flex w-full items-center justify-between gap-4 px-5 py-4 text-left hover:bg-slate-50" :aria-expanded="section.open"><span class="flex items-center gap-3"><span class="grid h-8 w-8 place-items-center rounded-lg bg-indigo-50 text-xs font-extrabold text-indigo-600" x-text="String(index + 1).padStart(2, '0')"></span><span><span class="block text-sm font-bold text-slate-900" x-text="section.title"></span><span class="block text-xs text-slate-500" x-text="section.subtitle"></span></span></span><span class="text-xl text-slate-400" x-text="section.open ? '−' : '+'"></span></button><div x-show="section.open" x-collapse class="border-t border-slate-100 px-5 pb-5 pt-5">
                    <template x-if="section.id === 'personal'"><div class="grid gap-4 sm:grid-cols-2"><div class="sm:col-span-2"><label class="field-label" for="full_name">Full name</label><input id="full_name" x-model="cv.name" class="field" placeholder="e.g. Muhammad Ahmed" autocomplete="name"></div><div><label class="field-label">Professional title</label><input x-model="cv.headline" class="field" placeholder="e.g. Full Stack Developer"></div><div><label class="field-label">City / country</label><input x-model="cv.location" class="field" placeholder="e.g. Lahore, Pakistan"></div><div><label class="field-label">Email</label><input type="email" x-model="cv.email" class="field" placeholder="you@example.com"></div><div><label class="field-label">Phone</label><input x-model="cv.phone" class="field" placeholder="+92 300 0000000"></div><div><label class="field-label">Website</label><input x-model="cv.website" class="field" placeholder="https://yourwebsite.com"></div><div><label class="field-label">LinkedIn</label><input x-model="cv.linkedin" class="field" placeholder="linkedin.com/in/yourname"></div><div><label class="field-label">GitHub</label><input x-model="cv.github" class="field" placeholder="github.com/yourname"></div><div class="sm:col-span-2"><label class="field-label">Profile photo <span class="font-normal text-slate-400">(optional)</span></label><div class="mt-2 flex items-center gap-4"><div class="grid h-14 w-14 shrink-0 place-items-center overflow-hidden rounded-full border-2 border-dashed border-slate-300 bg-slate-50"><template x-if="cv.photo"><img :src="cv.photo" alt="Profile photo preview" class="h-full w-full object-cover"></template><span x-show="!cv.photo" class="text-xl text-slate-300">+</span></div><input type="file" accept="image/png,image/jpeg" @change="uploadPhoto($event)" class="block w-full text-sm text-slate-500 file:mr-3 file:rounded-lg file:border-0 file:bg-indigo-50 file:px-3 file:py-2 file:text-xs file:font-bold file:text-indigo-600"></div></div><div class="sm:col-span-2 rounded-xl bg-slate-50 p-4"><div class="flex items-center justify-between"><div><p class="text-sm font-bold text-slate-800">Optional personal details</p><p class="text-xs text-slate-500">Only add these when relevant. CNIC is never shown by default.</p></div><label class="relative inline-flex cursor-pointer items-center"><input type="checkbox" x-model="cv.settings.showPersonalDetails" class="peer sr-only"><span class="h-6 w-11 rounded-full bg-slate-300 after:absolute after:left-[2px] after:top-[2px] after:h-5 after:w-5 after:rounded-full after:bg-white after:transition-all peer-checked:bg-indigo-600 peer-checked:after:translate-x-full"></span></label></div><div x-show="cv.settings.showPersonalDetails" class="mt-4 grid gap-4 sm:grid-cols-2"><div class="sm:col-span-2"><label class="field-label">Full address</label><input x-model="cv.fullAddress" class="field" placeholder="House, street, city, country"></div><div><label class="field-label">Nationality</label><input x-model="cv.nationality" class="field" placeholder="Pakistani"></div><div><label class="field-label">Domicile</label><input x-model="cv.domicile" class="field" placeholder="Lahore"></div><div><label class="field-label">Date of birth</label><input type="date" x-model="cv.dateOfBirth" class="field"></div><div><label class="field-label">CNIC / ID</label><input x-model="cv.cnicNumber" class="field" placeholder="Optional"></div></div></div></div></template>
                    <template x-if="section.id === 'summary'"><div><div class="flex items-center justify-between"><label class="field-label">Professional summary</label><span class="text-xs text-slate-400" x-text="wordCount() + ' words'"></span></div><textarea x-model="cv.summary" rows="6" maxlength="1200" class="field" placeholder="Summarize your experience, strongest skills and career direction in 3–5 lines."></textarea><div class="mt-3 flex flex-wrap gap-2"><button type="button" @click="summaryAction('short')" class="ai-button">Shorten</button><button type="button" @click="summaryAction('professional')" class="ai-button">Make professional</button><button type="button" @click="summaryAction('generate')" class="ai-button">Use guidance</button></div><p class="hint">Keep this focused on impact, specialization and the role you want next.</p></div></template>
                    <template x-if="section.id === 'experience'"><div class="space-y-4"><template x-for="(item, index) in cv.experience" :key="item.id"><div class="rounded-xl border border-slate-200 p-4"><div class="mb-4 flex items-center justify-between"><h3 class="text-sm font-bold text-slate-900">Experience <span x-text="index + 1"></span></h3><div class="flex gap-3"><button type="button" @click="duplicateItem('experience', index)" class="text-xs font-bold text-indigo-600">Duplicate</button><button type="button" @click="removeItem('experience', index)" class="text-xs font-bold text-rose-600">Remove</button></div></div><div class="grid gap-4 sm:grid-cols-2"><div><label class="field-label">Job title</label><input x-model="item.position" class="field" placeholder="Software Engineer"></div><div><label class="field-label">Company</label><input x-model="item.company" class="field" placeholder="Company name"></div><div><label class="field-label">Location</label><input x-model="item.location" class="field" placeholder="Remote / Lahore"></div><div><label class="field-label">Start date</label><input type="month" x-model="item.startDate" class="field"></div><div><label class="field-label">End date</label><input type="month" x-model="item.endDate" :disabled="item.current" class="field disabled:bg-slate-50"><label class="mt-2 flex items-center gap-2 text-xs text-slate-500"><input type="checkbox" x-model="item.current" class="rounded border-slate-300 text-indigo-600"> Currently working</label></div><div class="sm:col-span-2"><label class="field-label">Achievement bullets</label><textarea x-model="item.description" rows="4" class="field" placeholder="Start each achievement on a new line. Example: Increased organic traffic by 45%."></textarea><p class="hint">Start bullets with action verbs and show results where possible.</p></div></div></div></template><button type="button" @click="addExperience()" class="add-button">+ Add experience</button></div></template>
                    <template x-if="section.id === 'education'"><div class="space-y-4"><template x-for="(item, index) in cv.education" :key="item.id"><div class="rounded-xl border border-slate-200 p-4"><div class="mb-4 flex items-center justify-between"><h3 class="text-sm font-bold text-slate-900">Education <span x-text="index + 1"></span></h3><button type="button" @click="removeItem('education', index)" class="text-xs font-bold text-rose-600">Remove</button></div><div class="grid gap-4 sm:grid-cols-2"><div><label class="field-label">Degree</label><input x-model="item.degree" class="field" placeholder="BS Computer Science"></div><div><label class="field-label">Field / major</label><input x-model="item.field" class="field" placeholder="Software Engineering"></div><div class="sm:col-span-2"><label class="field-label">Institution</label><input x-model="item.institution" class="field" placeholder="University name"></div><div><label class="field-label">Location</label><input x-model="item.location" class="field" placeholder="Lahore"></div><div><label class="field-label">Start year</label><input x-model="item.startYear" class="field" placeholder="2018"></div><div><label class="field-label">End year</label><input x-model="item.endYear" class="field" placeholder="2022"></div><div><label class="field-label">CGPA / marks</label><input x-model="item.obtainedMarks" class="field" placeholder="3.6 or 920"></div><div><label class="field-label">Total marks</label><input x-model="item.totalMarks" class="field" placeholder="1100"></div><div><label class="field-label">Percentage</label><input x-model="item.percentage" class="field" placeholder="83.6%"></div><div class="sm:col-span-2"><label class="field-label">Description / honors</label><textarea x-model="item.description" rows="2" class="field" placeholder="Relevant coursework, honors or achievements"></textarea></div></div></div></template><button type="button" @click="addEducation()" class="add-button">+ Add education</button></div></template>
                    <template x-if="section.id === 'skills'"><div><div class="mb-3 flex items-center justify-between"><div><p class="field-label">Structured skills</p><p class="hint">Add skills relevant to the job you are applying for.</p></div><input x-model="skillSearch" class="field max-w-[180px]" placeholder="Search skills"></div><div class="space-y-3"><template x-for="(item, index) in cv.skills" :key="item.id"><div x-show="!skillSearch || item.name.toLowerCase().includes(skillSearch.toLowerCase())" class="grid gap-3 sm:grid-cols-[1.4fr_1fr_1fr_auto]"><input x-model="item.name" class="field" placeholder="Laravel"><select x-model="item.category" class="field"><option>Technical Skills</option><option>Programming</option><option>Web Development</option><option>Design</option><option>Digital Marketing</option><option>Soft Skills</option><option>Tools</option></select><select x-model="item.level" class="field"><option value="">Proficiency</option><option>Basic</option><option>Intermediate</option><option>Professional</option><option>Advanced</option><option>Expert</option></select><button type="button" @click="removeItem('skills', index)" class="px-2 text-lg text-rose-500" aria-label="Remove skill">×</button></div></template></div><div class="mt-3 flex flex-wrap gap-2"><template x-for="suggestion in skillSuggestions" :key="suggestion"><button type="button" @click="addSkill(suggestion)" class="rounded-full border border-slate-200 px-3 py-1.5 text-xs font-semibold text-slate-600 hover:border-indigo-400 hover:text-indigo-600" x-text="'+ ' + suggestion"></button></template></div><button type="button" @click="addSkill()" class="add-button mt-4">+ Add skill</button></div></template>
                    <template x-if="section.id === 'projects'"><div class="space-y-4"><template x-for="(item, index) in cv.projects" :key="item.id"><div class="rounded-xl border border-slate-200 p-4"><div class="mb-4 flex items-center justify-between"><h3 class="text-sm font-bold text-slate-900">Project <span x-text="index + 1"></span></h3><button type="button" @click="removeItem('projects', index)" class="text-xs font-bold text-rose-600">Remove</button></div><div class="grid gap-4 sm:grid-cols-2"><div><label class="field-label">Project name</label><input x-model="item.name" class="field" placeholder="Medical Management System"></div><div><label class="field-label">Your role</label><input x-model="item.role" class="field" placeholder="Full Stack Developer"></div><div><label class="field-label">Technologies</label><input x-model="item.technologies" class="field" placeholder="Laravel, PHP, MySQL"></div><div><label class="field-label">Project URL</label><input type="url" x-model="item.url" class="field" placeholder="https://example.com"></div><div><label class="field-label">GitHub URL</label><input type="url" x-model="item.githubUrl" class="field" placeholder="https://github.com/..."></div><div class="sm:col-span-2"><label class="field-label">Description and key achievements</label><textarea x-model="item.description" rows="3" class="field" placeholder="What you built, tools used and the result achieved..."></textarea></div></div></div></template><button type="button" @click="addProject()" class="add-button">+ Add project</button></div></template>
                    <template x-if="section.id === 'certifications'"><div class="space-y-4"><template x-for="(item, index) in cv.certifications" :key="item.id"><div class="rounded-xl border border-slate-200 p-4"><div class="mb-4 flex items-center justify-between"><h3 class="text-sm font-bold text-slate-900">Certification <span x-text="index + 1"></span></h3><button type="button" @click="removeItem('certifications', index)" class="text-xs font-bold text-rose-600">Remove</button></div><div class="grid gap-4 sm:grid-cols-2"><div><label class="field-label">Certification name</label><input x-model="item.name" class="field" placeholder="AWS Solutions Architect"></div><div><label class="field-label">Organization</label><input x-model="item.organization" class="field" placeholder="Amazon Web Services"></div><div><label class="field-label">Issue date</label><input type="month" x-model="item.issueDate" class="field"></div><div><label class="field-label">Expiry date</label><input type="month" x-model="item.expiryDate" :disabled="item.noExpiry" class="field disabled:bg-slate-50"><label class="mt-2 flex items-center gap-2 text-xs text-slate-500"><input type="checkbox" x-model="item.noExpiry" class="rounded border-slate-300 text-indigo-600"> No expiry</label></div><div><label class="field-label">Credential ID</label><input x-model="item.credentialId" class="field" placeholder="ABC-123"></div><div><label class="field-label">Credential URL</label><input type="url" x-model="item.credentialUrl" class="field" placeholder="https://..."></div></div></div></template><button type="button" @click="addCertification()" class="add-button">+ Add certification</button></div></template>
                    <template x-if="section.id === 'languages'"><div class="space-y-3"><template x-for="(item, index) in cv.languages" :key="item.id"><div class="grid grid-cols-[1fr_1fr_auto] gap-3"><input x-model="item.name" class="field" placeholder="English"><select x-model="item.proficiency" class="field"><option value="">Proficiency</option><option>Native</option><option>Fluent</option><option>Professional</option><option>Intermediate</option><option>Basic</option></select><button type="button" @click="removeItem('languages', index)" class="px-2 text-lg text-rose-500" aria-label="Remove language">×</button></div></template><button type="button" @click="addLanguage()" class="add-button">+ Add language</button></div></template>
                    <template x-if="section.id === 'references'"><div><div class="mb-4 flex items-center justify-between rounded-xl bg-slate-50 p-3"><div><p class="text-sm font-bold text-slate-800">References display</p><p class="text-xs text-slate-500">Modern CVs usually keep contacts private.</p></div><select x-model="cv.settings.referenceMode" class="field w-auto"><option value="request">Available upon request</option><option value="full">Show full references</option></select></div><div x-show="cv.settings.referenceMode === 'full'" class="space-y-4"><template x-for="(item, index) in cv.references" :key="item.id"><div class="rounded-xl border border-slate-200 p-4"><div class="mb-4 flex items-center justify-between"><h3 class="text-sm font-bold text-slate-900">Reference <span x-text="index + 1"></span></h3><button type="button" @click="removeItem('references', index)" class="text-xs font-bold text-rose-600">Remove</button></div><div class="grid gap-4 sm:grid-cols-2"><input x-model="item.name" class="field" placeholder="Reference name"><input x-model="item.position" class="field" placeholder="Position"><input x-model="item.company" class="field" placeholder="Company"><input type="email" x-model="item.email" class="field" placeholder="Email"><input x-model="item.phone" class="field" placeholder="Phone"><input x-model="item.relationship" class="field" placeholder="Relationship"></div></div></template><button type="button" @click="addReference()" class="add-button">+ Add reference</button></div></div></template>
                    <template x-if="section.id === 'design'"><div class="grid gap-4 sm:grid-cols-2"><div class="sm:col-span-2"><label class="field-label">Template</label><div class="grid grid-cols-2 gap-3 sm:grid-cols-3"><template x-for="item in templates" :key="item.slug"><button type="button" @click="setTemplate(item.slug)" class="rounded-xl border p-2 text-left transition" :class="template === item.slug ? 'border-indigo-500 bg-indigo-50 ring-2 ring-indigo-100' : 'border-slate-200 hover:border-indigo-300'"><div class="mb-2 h-16 rounded-lg bg-gradient-to-br from-slate-100 to-slate-300 p-2"><div class="h-1.5 w-2/3 bg-slate-700"></div><div class="mt-2 grid grid-cols-3 gap-1"><span class="h-8 bg-white"></span><span class="col-span-2 h-8 bg-white"></span></div></div><span class="text-xs font-bold text-slate-800" x-text="item.name"></span><span class="block text-[10px] text-slate-500" x-text="item.description"></span></button></template></div></div><div><label class="field-label">Accent color</label><div class="flex flex-wrap gap-2"><template x-for="color in accentColors" :key="color"><button type="button" @click="cv.settings.accent = color" class="h-8 w-8 rounded-full border-2" :class="cv.settings.accent === color ? 'border-slate-900 ring-2 ring-slate-200' : 'border-white'" :style="`background:${color}`" :aria-label="'Use accent ' + color"></button></template></div></div><label class="flex items-center gap-3 text-sm font-semibold text-slate-700"><input type="checkbox" x-model="cv.settings.atsMode" class="rounded border-slate-300 text-indigo-600"> ATS-friendly mode</label></div></template>
                </div></section></template><div class="rounded-2xl bg-slate-900 p-5 text-white"><div class="flex items-center justify-between gap-4"><div><p class="font-bold">Your draft is private in this browser</p><p class="mt-1 text-xs text-slate-300">Autosave runs after a short pause. Download when you are ready.</p></div><button type="submit" class="rounded-lg bg-white px-4 py-2 text-sm font-bold text-slate-900 hover:bg-indigo-50">Save CV</button></div></div></form>
                <aside class="hidden lg:sticky lg:top-[76px] lg:block print:block"><div class="mb-3 flex items-center justify-between print:hidden"><div><p class="text-sm font-bold text-slate-900">Live preview</p><p class="text-xs text-slate-500"><span x-text="activeTemplateName()"></span> · A4 paper</p></div><span class="rounded-full bg-emerald-50 px-3 py-1 text-xs font-bold text-emerald-700">Auto-updating</span></div><div :data-cv-template="template" class="mx-auto max-w-[760px] overflow-hidden rounded-sm bg-white shadow-xl ring-1 ring-slate-200">@foreach ($templates as $templateOption)<template x-if="template === @js($templateOption['slug'])">@include('cv-preview.'.$templateOption['slug'])</template>@endforeach</div></aside></div></main>
        <div x-show="mobilePreview" x-cloak class="fixed inset-0 z-50 bg-slate-900/60 p-3 lg:hidden" role="dialog" aria-modal="true" @keydown.escape.window="mobilePreview = false"><div class="flex h-full flex-col overflow-hidden rounded-2xl bg-slate-100"><div class="flex items-center justify-between border-b border-slate-200 bg-white px-4 py-3"><p class="font-bold text-slate-900">Live preview</p><button type="button" @click="mobilePreview = false" class="rounded-lg px-3 py-1 text-xl text-slate-500" aria-label="Close preview">×</button></div><div class="flex-1 overflow-auto p-3"><div :data-cv-template="template" class="mx-auto max-w-[760px] overflow-hidden rounded-sm bg-white shadow-xl">@foreach ($templates as $templateOption)<template x-if="template === @js($templateOption['slug'])">@include('cv-preview.'.$templateOption['slug'])</template>@endforeach</div></div></div></div>
    </div>
    @include('components.cv-template-switcher', ['templates' => $templates, 'defaultTemplate' => $defaultTemplate])
    @include('cv-preview.styles')
    <script>
        function cvBuilder(templates, defaultTemplate) {
            const id = () => Date.now() + Math.random();
            const blank = { education:() => ({id:id(),degree:'',field:'',institution:'',location:'',startYear:'',endYear:'',totalMarks:'',obtainedMarks:'',percentage:'',description:''}), experience:() => ({id:id(),position:'',company:'',location:'',startDate:'',endDate:'',current:false,description:''}), skill:(name='') => ({id:id(),name,category:'Technical Skills',level:''}), project:() => ({id:id(),name:'',role:'',technologies:'',url:'',githubUrl:'',description:''}), certification:() => ({id:id(),name:'',organization:'',issueDate:'',expiryDate:'',noExpiry:false,credentialId:'',credentialUrl:''}), language:() => ({id:id(),name:'',proficiency:''}), reference:() => ({id:id(),name:'',position:'',company:'',email:'',phone:'',relationship:''}) };
            const initialCv = () => ({name:'',headline:'',location:'',email:'',phone:'',website:'',linkedin:'',github:'',photo:'',summary:'',fullAddress:'',nationality:'',domicile:'',dateOfBirth:'',cnicNumber:'',education:[blank.education()],experience:[blank.experience()],skills:[blank.skill()],projects:[],certifications:[],languages:[blank.language()],references:[],settings:{template:defaultTemplate||'classic',accent:'#f4c400',atsMode:true,showPersonalDetails:false,referenceMode:'request'}});
            return { templates, template:defaultTemplate||'classic', cv:initialCv(), saveStatus:'idle', saveTimer:null, downloading:false, mobilePreview:false, skillSearch:'', accentColors:['#4f46e5','#2563eb','#0f766e','#059669','#7c3aed','#e11d48','#d97706'], skillSuggestions:['Laravel','PHP','JavaScript','SQL','Git','Figma','SEO','Communication'], sections:[{id:'personal',title:'Personal information',subtitle:'Name, contact and optional details',open:true},{id:'summary',title:'Professional summary',subtitle:'Make a strong first impression',open:false},{id:'experience',title:'Work experience',subtitle:'Show impact with achievement bullets',open:false},{id:'education',title:'Education',subtitle:'Academic background and honors',open:false},{id:'skills',title:'Skills',subtitle:'Relevant capabilities and proficiency',open:false},{id:'projects',title:'Projects',subtitle:'Especially valuable for students',open:false},{id:'certifications',title:'Certifications',subtitle:'Credentials and verification links',open:false},{id:'languages',title:'Languages',subtitle:'Your language proficiency',open:false},{id:'references',title:'References',subtitle:'Private by default',open:false},{id:'design',title:'Design',subtitle:'Template, accent and ATS mode',open:false}], init(){this.loadDraft();this.$watch('cv',()=>this.markChanged(),{deep:true});}, saveLabel(){return this.saveStatus==='saving'?'Saving...':this.saveStatus==='saved'?'Saved just now':'Unsaved changes';}, markChanged(){this.saveStatus='saving';clearTimeout(this.saveTimer);this.saveTimer=setTimeout(()=>this.saveDraft(),700);}, saveDraft(){localStorage.setItem('cvbuilder-draft',JSON.stringify(this.cv));localStorage.setItem('cvbuilder-template',this.template);this.saveStatus='saved';}, loadDraft(){try{const draft=JSON.parse(localStorage.getItem('cvbuilder-draft')||'null');if(draft)this.cv={...initialCv(),...draft,settings:{...initialCv().settings,...(draft.settings||{})}}}catch{localStorage.removeItem('cvbuilder-draft')}con